const careerNetUniversityMajorSchoolCount = 473;
const careerNetUniversityMajorNameCount = 10657;

class CareerNetUniversityMajorOffering {
  const CareerNetUniversityMajorOffering(
    this.schoolName,
    this.campusName,
    this.areaName,
    this.schoolUrl,
    this.majorName,
    this.catalogMajorName,
    this.category,
    this.schoolType,
    this.sourceMajorSeq,
    this.updatedAt,
  );

  final String schoolName;
  final String campusName;
  final String areaName;
  final String schoolUrl;
  final String majorName;
  final String catalogMajorName;
  final String category;
  final String schoolType;
  final String sourceMajorSeq;
  final String updatedAt;

  String get schoolLabel {
    if (campusName.isEmpty) {
      return schoolName;
    }
    return '$schoolName($campusName)';
  }

  bool matches(String query) {
    final trimmed = query.trim().toLowerCase();
    if (trimmed.isEmpty) {
      return true;
    }
    return schoolName.toLowerCase().contains(trimmed) ||
        campusName.toLowerCase().contains(trimmed) ||
        areaName.toLowerCase().contains(trimmed) ||
        majorName.toLowerCase().contains(trimmed) ||
        catalogMajorName.toLowerCase().contains(trimmed) ||
        category.toLowerCase().contains(trimmed) ||
        schoolType.toLowerCase().contains(trimmed);
  }
}

